UPDATE fp_identity_revision SET revision=revision+1,commit_nonce='account-rules-20261023' WHERE id=1 AND revision=40;
INSERT INTO fp_identity_guard(id) SELECT 0 WHERE NOT EXISTS(SELECT 1 FROM fp_identity_revision WHERE id=1 AND commit_nonce='account-rules-20261023');
CREATE TABLE fp_rules_sequence AS SELECT MAX(COALESCE((SELECT seq FROM sqlite_sequence WHERE name='auth_users'),9999),COALESCE((SELECT MAX(user_id) FROM auth_users),9999)) AS high_id;
CREATE TABLE auth_users_rules_next(user_id INTEGER PRIMARY KEY AUTOINCREMENT CHECK(user_id>=10000),display_name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('开发者','管理员','普通用户','只读用户')),staff_id INTEGER NOT NULL CHECK(typeof(staff_id)='integer' AND staff_id>=-1),password_hash TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),version INTEGER NOT NULL DEFAULT 1 CHECK(version>=1),CHECK((role='开发者' AND staff_id=0) OR (role IN ('管理员','只读用户') AND staff_id=-1) OR (role='普通用户' AND staff_id>0)));
INSERT INTO auth_users_rules_next SELECT user_id,display_name,role,CASE WHEN role='只读用户' THEN -1 ELSE staff_id END,password_hash,active,version+CASE WHEN role='只读用户' AND staff_id<>-1 THEN 1 ELSE 0 END FROM auth_users;
CREATE TABLE fp_rules_onboarding AS SELECT * FROM auth_onboarding;
DROP TABLE auth_onboarding;
DROP TABLE auth_users;
ALTER TABLE auth_users_rules_next RENAME TO auth_users;
CREATE TABLE auth_onboarding(user_id TEXT PRIMARY KEY REFERENCES auth_users(user_id) ON DELETE CASCADE,step INTEGER NOT NULL DEFAULT 0,completed_at TEXT);
INSERT INTO auth_onboarding SELECT * FROM fp_rules_onboarding;
DROP TABLE fp_rules_onboarding;
UPDATE sqlite_sequence SET seq=MAX(seq,(SELECT high_id FROM fp_rules_sequence)) WHERE name='auth_users';
CREATE TABLE auth_id_sequence_rules_next(id INTEGER PRIMARY KEY CHECK(id=1),next_id INTEGER NOT NULL CHECK(next_id>=10000));
INSERT INTO auth_id_sequence_rules_next SELECT id,MAX(next_id,10000,(SELECT high_id+1 FROM fp_rules_sequence)) FROM auth_id_sequence;
DROP TABLE auth_id_sequence;
ALTER TABLE auth_id_sequence_rules_next RENAME TO auth_id_sequence;
DROP TABLE fp_rules_sequence;
PRAGMA foreign_key_check;
